/// </summary>
[ExtensionOf(formStr(EcoResProductInformationDialog))]
final class EcoResProductInformationDialog_frm_Extension
{
}

Method.Source:
/// <summary>
/// Enables OPK Button
/// </summary>
/// <param name = "_formRun">Form</param>
public void NDXsetMagentoOPKEnabled(FormRun _formRun)
{
    InventTable inventTable = _formRun.dataSource(formDataSourceStr(EcoResProductInformationDialog, InventTable)).cursor();
    FormControl NDXOpenProductInOPKCatalog = _formRun.design().controlName(formControlStr(EcoResProductInformationDialog, NDXOpenProductInOPKCatalog));

    NDXOpenProductInOPKCatalog.enabled(false);
    if(inventTable.NDX_ShowItemInOnlineCatalog && NDXMagentoProducts::find(inventTable.NDXModelNumber))
    {
        NDXOpenProductInOPKCatalog.enabled(true);
    }
}
